/* 食盆贴片（叠在主页右下角餐盒区）。
   bowl.bin = u32 n + u32 off[n]；每片 = u16 x0,y0,w,h + **A 平面 + K 平面**。
   A 平面 = 1 表示这片像素「覆盖」（否则露底图）；K 平面 = 1 表示黑、0 表示白。
   ★ 与 win/cat 的单平面不同：贴片里**白像素也要盖住底图**（骨头高光、盆沿），
     所以要两张平面，落屏 = A ? (K ? 0 : 255) : 不动。
   ★ 画在猫之前（盆属于房间层，猫压盆）—— 见 spec §17.7。 */
/* ★★ 2026-09-22 晚：**深夜食物网点已按用户拍板取消**。
   原委：房间底面深夜是网点化的（room.bin 深夜页地板 = 8×8 tile、密度 0.438），
   而贴片是「实心黑 + 死白」两块 → 贴片覆盖区墨点占比 **0.728**，比周围地板黑 66%，
   **最终用户改主意：「食物在深夜还是不要加网点了，取消这条」→ 代码已整体移除。**
   若日后要恢复，要点（别再重新推导一遍）：
     · 黑填充（四邻域都是墨）打 tile；轮廓线**保实心**（否则形状糊）
     · 白处打 ((x-y)&3)==0 的 25% 稀网点；判据必须用**原来的黑白** kk，不能用打过的 kk
     · ★ tile 相位锚**屏幕坐标**（x%8 / y%8），不能用贴片局部坐标，否则与周围错相
     · 预览脚本：`_preview/preview_night_food_dot.py`；对账脚本 `_preview/_verify_bowl_dither.py` */
static void fb_apply_bowl(int food, int state)
{
    if (food < 0 || food >= N_FOOD) return;
    /* ★ 贴片只有两档（1 满 / 2 残渣），逻辑上却有 4 个状态：
       「进食中」碗里还有食 → 照样画「满」；残渣 → 画「残渣」；空 → 不贴（露底图的餐盒）。 */
    int vis = (state == BOWL_FULL || state == BOWL_EATING) ? 1
            : (state == BOWL_RESIDUE ? 2 : 0);
    if (vis == 0) return;
    int idx = food * 2 + (vis - 1);              /* 1 满 / 2 残渣 */

    uint32_t n;
    if (!bowl_start || bowl_end == bowl_start) return;   /* ★2026-10-23 修（M8）：PSRAM 装载失败时 bowl_start=NULL/长度0 —— 注释承诺的"降级不画"此前缺判空，会 NULL 解引用 */
    memcpy(&n, bowl_start, 4);
    if ((uint32_t)idx >= n) return;
    uint32_t off;
    memcpy(&off, bowl_start + 4 + 4 * idx, 4);
    const uint8_t *sp = bowl_start + off;

    uint16_t x0, y0, w, h;
    memcpy(&x0, sp, 2); memcpy(&y0, sp + 2, 2);
    memcpy(&w,  sp + 4, 2); memcpy(&h, sp + 6, 2);
    int row = (w + 7) / 8;
    int lay = row * h;
    const uint8_t *A = sp + 8;
    const uint8_t *K = A + lay;
    /* ★2026-10-13 任务二 P2-2 修：偏移表里的 off 必须查上界（只查 idx<n 不够）——
       偏移表写坏 / 文件被截断时，`sp + 8 + 2*lay` 会越过 bowl.bin 末尾 ⇒ 越界读
       flash（花屏 / HardFault）。与 fb_apply_cat（471）/ fb_bubble_stamp 同款。
       贴片 = 8 字节头(x0,y0,w,h) + A/K 两层各 row*h。 */
    if ((size_t)off + 8 + 2 * (size_t)lay > (size_t)(bowl_end - bowl_start)) return;
    if (x0 >= EPD_W || y0 >= EPD_H) return;
    int x1 = (x0 + w > EPD_W) ? EPD_W : x0 + w;
    int y1 = (y0 + h > EPD_H) ? EPD_H : y0 + h;
    for (int y = y0; y < y1; ++y) {
        int sy = y - y0;
        for (int x = x0; x < x1; ++x) {
            int sx = x - x0;
            if (!bit_get(A, row, sy, sx)) continue;
            int k = bit_get(K, row, sy, sx) ? 1 : 0;
            fb[y][x] = k ? 0 : 255;
        }
    }
}

/* ★ 状态贴片（2026-09-21 用户新增素材；★ 2026-09-25 深夜并入 WiFi 三态成 patch.bin）。
   patch.bin 与 bowl.bin **逐字节同构**：u32 n + u32 off[n]；
   每片 = u16 x0,y0,w,h + A 平面（覆盖）+ K 平面（墨）。落屏 = A ? (K ? 黑 : 白) : 不动。
   kind 见文件头部 PAT_* 定义：0=外出立牌 · 1=明信片角标 · 2..4=WiFi 有/弱/无 · 5=礼物。 */

/* 读第 kind 片贴片头里的 x0（越界返回 0）—— 礼物/明信片组合定位用 */
static uint16_t patch_head_x(int kind)
{
    if (kind < 0 || kind >= N_PATCH) return 0;
    if (!patch_start || patch_end == patch_start) return 0;   /* ★2026-10-23 修（M8）：判空，同 fb_apply_bowl */
    uint32_t n;
    memcpy(&n, patch_start, 4);
    if ((uint32_t)kind >= n) return 0;
    uint32_t off;
    memcpy(&off, patch_start + 4 + 4 * kind, 4);
    /* ★2026-10-13 任务二 P2-2 修：off 上界校验（只读 2 字节头也要查）—— 偏移表写坏 /
       文件截断时 patch_start + off 越界。同 fb_apply_cat 守卫。 */
    if ((size_t)off + 2 > (size_t)(patch_end - patch_start)) return 0;
    uint16_t x0;
    memcpy(&x0, patch_start + off, 2);
    return x0;
}

/* ★ dx = 落屏时的 x 位移（贴片头坐标 + dx）。★2026-09-25 礼物贴片专用：
   只有礼物没有明信片时，礼盒从 (117,7) 右移到明信片角标的位（154,7），
   位移量 = 明信片贴片头 x − 礼物贴片头 x（运行时从 patch.bin 读，不写死像素）。 */
static void fb_apply_patch_dx(int kind, int dx)
{
    if (kind < 0 || kind >= N_PATCH) return;
    if (!patch_start || patch_end == patch_start) return;   /* ★2026-10-23 修（M8）：判空，同 fb_apply_bowl */

    uint32_t n;
    memcpy(&n, patch_start, 4);
    if ((uint32_t)kind >= n) return;
    uint32_t off;
    memcpy(&off, patch_start + 4 + 4 * kind, 4);
    /* ★R112 修：与 fb_apply_patch_xy 同款 —— 在读头**之前**先粗校验片头 8 字节落在区内，
       避免 off 越界时先 memcpy 读界外、再拿垃圾 w/h 去算 lay（详见那里的注释）。 */
    if ((size_t)off + 8 > (size_t)(patch_end - patch_start)) return;
    const uint8_t *sp = patch_start + off;

    uint16_t x0, y0, w, h;
    memcpy(&x0, sp, 2); memcpy(&y0, sp + 2, 2);
    memcpy(&w,  sp + 4, 2); memcpy(&h, sp + 6, 2);
    x0 = (uint16_t)(x0 + dx);
    int row = (w + 7) / 8;
    int lay = row * h;
    const uint8_t *A = sp + 8;
    const uint8_t *K = A + lay;
    /* ★2026-10-13 任务二 P2-2 修：off 上界校验（同 fb_apply_cat / fb_apply_bowl）——
       偏移表写坏 / 文件截断时 sp + 8 + 2*lay 越过 patch.bin 末尾 = 越界读 flash。 */
    if ((size_t)off + 8 + 2 * (size_t)lay > (size_t)(patch_end - patch_start)) return;
    if (x0 >= EPD_W || y0 >= EPD_H) return;
    int x1 = (x0 + w > EPD_W) ? EPD_W : x0 + w;
    int y1 = (y0 + h > EPD_H) ? EPD_H : y0 + h;
    for (int y = y0; y < y1; ++y) {
        int sy = y - y0;
        for (int x = x0; x < x1; ++x) {
            int sx = x - x0;
            if (!bit_get(A, row, sy, sx)) continue;
            fb[y][x] = bit_get(K, row, sy, sx) ? 0 : 255;
        }
    }
}

static void fb_apply_patch(int kind)
{
    fb_apply_patch_dx(kind, 0);
}

