/* ★★2026-10-22 用户令：邮件收藏（两套系统共用一份 NVS blob）。
   编码：mypost 条目 key = ts（Unix < 2^31，顶端 bit 恒 0）；旧明信片 key = post 索引，
   存时置顶 bit（FAV_KIND_POST）区分。⇒ 每个收藏只占 4B，128 条 = 512B，DRAM 友好。
   注意：mypost 的 ts 可能为 0（空槽，不收藏）→ 不入表。 */
#define FAV_MAX       32
#define FAV_KIND_POST 0x80000000u
typedef struct { int n; uint32_t it[FAV_MAX]; } fav_store_t;
static fav_store_t s_fav;
static bool        s_fav_ready = false;

static void fav_load(void)
{
    fav_store_t buf;
    if (loot_nvs_get_blob("mail_fav", &buf, sizeof(buf)) && buf.n >= 0 && buf.n <= FAV_MAX)
        s_fav = buf;
    else
        s_fav.n = 0;
    s_fav_ready = true;
}
static void fav_ensure(void) { if (!s_fav_ready) fav_load(); }
static uint32_t fav_enc(uint8_t kind, uint32_t key)
{
    return (kind == 0) ? key : (FAV_KIND_POST | (key & 0x7FFFFFFFu));
}
static bool fav_has(uint8_t kind, uint32_t key)
{
    fav_ensure();
    const uint32_t v = fav_enc(kind, key);
    for (int i = 0; i < s_fav.n; ++i) if (s_fav.it[i] == v) return true;
    return false;
}
static void fav_toggle(uint8_t kind, uint32_t key)
{
    fav_ensure();
    if (kind == 0 && key == 0) return;            /* 空槽不收藏 */
    const uint32_t v = fav_enc(kind, key);
    for (int i = 0; i < s_fav.n; ++i)
        if (s_fav.it[i] == v) {                   /* 已收藏 → 取消 */
            for (int j = i; j + 1 < s_fav.n; ++j) s_fav.it[j] = s_fav.it[j + 1];
            --s_fav.n;
            loot_nvs_set_blob("mail_fav", &s_fav, sizeof(s_fav));
            return;
        }
    if (s_fav.n < FAV_MAX) {                      /* 未收藏 → 加入 */
        s_fav.it[s_fav.n++] = v;
        loot_nvs_set_blob("mail_fav", &s_fav, sizeof(s_fav));
    }
}

/* 操作页当前条目句柄（kind 同 fav：0=mypost·key=ts / 1=post·key=索引；can_delete=显示删除行）*/
