/* ★2026-10-22 用户令：详情页「返回」目标。正常从列表进 = 回列表；从「我的收藏」进 = 回收藏
   （否则会跳进该明信片所属分类）。进详情前由打开方写入。 */
page_t s_myp_back      = PG_MYPOST_LIST;
static page_t s_postitem_back = PG_POST_LIST;

/* ═══ ★R142 明信片详情页的「翻张域」═══════════════════════════════════════════
   用户报：「点进我的收藏 → 上下滑，翻的不是我收藏的明信片，而是直接跳到常规信件序列」。
   病根：`post_goto()` 一直按**全局已收到集合**（post_got_cnt / post_order）翻张，
   它根本不知道"这次是从收藏进来的"，所以从收藏点开第 1 张后，往下滑就滑进全集。
   修法：**不新增状态**，域判据直接看 `s_postitem_back`（打开方进详情前写入）——
   == PG_FAV_LIST 就是收藏域。这样「从收藏进 → 返回 → 再从列表进」会**自动**切回全集域。
   ⚠ 收藏表 `s_fav` 里同时存「明信片」和「照片信件」两种项（靠 FAV_KIND_POST 位区分），
     而 PG_POST_ITEM 只显示内置明信片 ⇒ 翻张只在该表的**明信片项**里走，跳过照片信件项。 */
bool post_fav_domain(void)
{
    return s_postitem_back == PG_FAV_LIST;
}

/* 把收藏表里的**明信片项**按收藏顺序摊成 raw 下标数组（跳过照片信件项 / 已失效项）。 */
static int fav_post_list(int *list, int cap)
{
    fav_ensure();
    int n = 0;
    for (int i = 0; i < s_fav.n && n < cap; ++i) {
        const uint32_t v = s_fav.it[i];
        if (!(v & FAV_KIND_POST)) continue;                  /* 照片信件项不参与翻张 */
        const int idx = (int)(v & 0x7FFFFFFFu);
        if (idx < 0 || idx >= API_POST_IDX) continue;   /* ★R144：API 专用槽不可收藏 */
        if (!post_is_got(idx)) continue;                      /* 已失效项跳过（打开时会被摘掉） */
        list[n++] = idx;
    }
    return n;
}

/* 收藏域内翻一张：返回下一张的 raw 下标；-1 = 不在收藏域 / 当前片不在收藏里（交回原逻辑） */
int post_fav_step(int cur_raw, int delta)
{
    if (!post_fav_domain()) return -1;
    int list[FAV_MAX];
    const int n = fav_post_list(list, FAV_MAX);
    if (n <= 0) return -1;
    int cur = -1;
    for (int i = 0; i < n; ++i) if (list[i] == cur_raw) { cur = i; break; }
    if (cur < 0) return -1;                                   /* 当前片不在收藏里 → 不当收藏域 */
    return list[(cur + delta + n) % n];                        /* 到头回绕，与全集域口径一致 */
}

/* 收藏域内的位置（0-based）+ 总数 —— 详情页角标要用，否则从收藏进还显示全集编号。 */
bool post_fav_pos(int cur_raw, int *pos, int *total)
{
    if (!post_fav_domain()) return false;
    int list[FAV_MAX];
    const int n = fav_post_list(list, FAV_MAX);
    if (n <= 0) return false;
    for (int i = 0; i < n; ++i) {
        if (list[i] == cur_raw) {
            if (pos)   *pos   = i;
            if (total) *total = n;
            return true;
        }
    }
    return false;
}


