static const fb_cap_t *fb_cap_pool(int *n)
{
    switch (g_lang) {
    case LANG_EN:  *n = (int)(sizeof(FB_CAP_EN)  / sizeof(FB_CAP_EN[0]));  return FB_CAP_EN;
    case LANG_JA:  *n = (int)(sizeof(FB_CAP_JA)  / sizeof(FB_CAP_JA[0]));  return FB_CAP_JA;
    case LANG_ZHT: *n = (int)(sizeof(FB_CAP_ZHT) / sizeof(FB_CAP_ZHT[0])); return FB_CAP_ZHT;
    default:       *n = (int)(sizeof(FB_CAP_ZH)  / sizeof(FB_CAP_ZH[0]));  return FB_CAP_ZH;
    }
}

/* ★R170：配文**只剩本地兜底**这一半 —— 模型写文案的那一半搬进了 ws_api_scene
   （画面与配文一次调用同源，见 net_sync.c）。本函数只在整条文字通道挂了时用，
   所以不再发网络请求：从本机四语池随机抽一组，保证断网也有字、且不是同一句。
   ★R164 的由来保留在这里：用户报「文案又变成『这是我在上海附近走走』」，那不是
   模型写的，是写死的兜底模板；串口 r163 实证真因是文字通道超时（err=28679 http=-1）。 */
static void api_caption_local(const char *city, char *title, int tcap, char *body, int bcap)
{
    if (!title || !body || tcap <= 1 || bcap <= 1) return;
    title[0] = body[0] = 0;
    const char *home = (city && city[0]) ? city
                     : ((g_app.cfg && g_app.cfg->city[0]) ? g_app.cfg->city : "家");
    int n = 0;
    const fb_cap_t *pool = fb_cap_pool(&n);
    const int pick = (n > 0) ? (int)(esp_random() % (uint32_t)n) : -1;
    if (pick >= 0) {
        api_u8ncpy(title, pool[pick].t, tcap);
        api_u8ncpy(body,  pool[pick].b, bcap);
        post_font_fix(title, tcap);
        post_font_fix(body, bcap);
    }
    if (!body[0]) {                                       /* 池里全被字库滤掉 → 老模板 */
        char hs[40];
        ai_city_short(home, hs, (int)sizeof(hs));         /* ★R162：模板也别写「上海市」 */
        snprintf(body, (size_t)bcap, T("这是我在%s附近走走"), t_(hs));
        post_font_fix(body, bcap);                 /* ★R170 全检：T() 拼串后仍要按字库清洗 */
        api_u8ncpy(title, T("来自散步"), tcap);
        ESP_LOGW(TAG, "★R170 AI 图卡配文兜底：老模板（文字通道没出文案）");
    } else {
        ESP_LOGW(TAG, "★R170 AI 图卡配文兜底：#%d「%s」/ %s（文字通道没出文案）",
                 pick, title, body);
    }
}

/* ══ ★R170：一张 AI 明信片的**统一简报**（出图提示词 / 标题 / 正文 / 寄自哪）══════
   用户口径（2026-11-10）：「新增 22 个日常场景，那你不又全部固定了吗？我要的是它
   随机生成 —— 理想情况玩 100 年也能不停出新的图。要只有 22 个场景，我为什么不
   提前弄好？提前弄好掌控性还高一点。」
   ⇒ 分工改成：
     · **固件**只掷「寄自哪座城」（近城为主、远城偶发，ai_visit_city）与
       「地标类 / 日常类」（35% / 65%）—— 这是玩家能感知的**地理感**，必须可控；
     · **具体画面**由文字模型每张现编（ws_api_scene），同一座城每次的角落都不同，
       固件里不存在能穷举的清单；
     · 配文与画面同一次调用产出，天然同源，不会「图是巷口、字写外滩」；
     · 断网/限流 → 回落到本地旧路（场景池 + 城市地标关键词 + 本地配文池），
       那一张退回「清单里的画面」，但绝不出不了片。
   画风尾巴（铅笔速写 / 大面积留白）永远由固件拼在最后，模型改不了画风。 */
void post_brief_make(post_brief_t *b)
{
    post_brief_make_at(b, NULL);
}

void post_brief_make_at(post_brief_t *b, const char *fixed_where)
{
    if (!b) return;
    memset(b, 0, sizeof(*b));
    const char *home = (g_app.cfg && g_app.cfg->city[0]) ? g_app.cfg->city : "家";
    if (fixed_where && fixed_where[0]) {
        /* ★R173：远行归来 —— 目的地是「这一趟去哪」的既定事实，不能随机辐射；
           但画面和配文照样每张现编，且允许带目的地味道（landmark=true）。 */
        snprintf(b->where, sizeof(b->where), "%s", fixed_where);
        b->landmark = true;
    } else {
        b->landmark = ((int)(esp_random() % 100u) < 35);
        if (b->landmark) ai_visit_city(home, b->where, sizeof(b->where), 50);
        else             snprintf(b->where, sizeof(b->where), "%s", home);
    }

    b->ai_scene = ws_api_scene(b->where, b->landmark, g_app.st.weather,
                               b->scene, (int)sizeof(b->scene),
                               b->title, (int)sizeof(b->title),
                               b->body,  (int)sizeof(b->body));
    if (!b->ai_scene) {
        if (b->landmark) city_place_en(b->where, b->scene, (int)sizeof(b->scene));
        else             ai_daily_scene_build(b->scene, (int)sizeof(b->scene));
        api_caption_local(b->where, b->title, (int)sizeof(b->title),
                          b->body, (int)sizeof(b->body));
    }
    /* 上屏前的统一清洗（模型爱加标点 / 空格 / 生僻字）：与远行日记同一条流水线 */
    post_font_fix_title(b->title, (int)sizeof(b->title));
    post_font_fix(b->body,  (int)sizeof(b->body));
    api_cjk_tighten(b->title);
    api_cjk_tighten(b->body);
    /* ★2026-11-12 用户令：模型标题不合池子风格（「旧车暖影」那类）→ 换成池里的真标题。
       只在中文/繁体态做 —— 英文/日文标题本来就是外语，不适用池子的中文口径。 */
    if (g_lang == LANG_ZH || g_lang == LANG_ZHT) {
        static int s_title_abs = 0;   /* 连续「偏抽象」标题数（RAM，重启清零够用）*/
        const bool bad  = !post_title_ok(b->title);
        const bool absx = (!bad && post_title_abstract(b->title));
        if (bad || (absx && s_title_abs >= 2)) {
            const char *pt = g_posts[esp_random() % (unsigned)N_POST].title;
            if (pt && pt[0]) {
                ESP_LOGW(TAG, "★ 标题%s（「%s」）→ 换成池内标题「%s」",
                         bad ? "含怪字符/抒情词" : "连续偏抽象", b->title, pt);
                api_u8ncpy(b->title, pt, (int)sizeof(b->title));
                post_font_fix_title(b->title, (int)sizeof(b->title));
            }
            s_title_abs = 0;
        } else if (absx) {
            s_title_abs++;
        } else {
            s_title_abs = 0;
        }
    }
    if (!b->title[0]) {
        api_u8ncpy(b->title, T("来自散步"), (int)sizeof(b->title));
        post_font_fix_title(b->title, (int)sizeof(b->title));   /* ★R170 全检：兜底标题也要按字库清洗 */
    }
    if (!b->body[0]) {
        char hs[40];
        ai_city_short(b->where, hs, (int)sizeof(hs));
        snprintf(b->body, sizeof(b->body), T("这是我在%s附近走走"), t_(hs));
        post_font_fix(b->body, (int)sizeof(b->body));
    }
    /* ★★2026-11-12 用户令（实机报「纸伞残迹半斜旁 / 边 雨滴打湿 像读诗」）：
       **不再由固件强行插换行**。原来这里调 api_caption_break() 按「每行 11 字」硬切，
       结果把「旁边」劈成「旁 / 边」；更根本的是——背面绘制 fb_text_note_page() 本来就按
       实际像素宽度自动折行，且遇到空格优先在词间断（note_line_span 里的 brk），
       根本不需要这一层。让它自然折行，正文才不会像断句诗。 */
    /* ★★2026-11-12 用户令（实机报「虽然说是上海但我完全看不出这是什么东西」）：
       旧尾巴写 `generous negative space` + `calm and quiet` ⇒ 模型把主体画得又小又淡，
       1bit 200×200 上几乎只剩几根线，认不出画的是什么。
       改成「单主体、居中、占满画面、粗轮廓、高对比」，留白只留一圈边 ——
       画风还是铅笔速写，但主体必须撑满、必须能认出是那个东西。 */
    /* ★★2026-11-12 用户令（第二版）：要**蚀刻版画**那一套，且必须放最前面 ——
       api_image_gen() 的 POST 路径用 `"%.200s"` 截断 prompt，旧的画风词全在尾部，
       被切掉之后模型根本收不到风格约束（用户原话「他好像都没有按照那个去生成」）。
       所以「蚀刻 / 排线 / 高对比」三个词前置，scene 接在后面，尾部只留最次要的一句。 */
    /* ★★2026-11-12 用户令（第三版）：要**线描**，不要色块。
       上一版写 `etching + ink hatching + high contrast` —— 排线 × 高对比在 1-bit 下
       必然糊成大面积黑（用户原话「现在生成的像以色块为主」）。历史那版
       `soft pencil sketch, clean simple lines, generous negative space` 才是他要的线描感。
       这一版把两者取中：**线条为主 + 显式禁掉色块**，但不写 `generous negative space`
       （那会把主体画得太小、又回到「看不出是什么」）。
       ⚠ `no shading / no hatching / no solid black` 三个否定词必须都留 —— 少一个模型就会补灰。 */
    /* ★★2026-11-12 用户令（第四版，实机报「上左右都有黑色的部分」）：
       上一版结尾写 `one subject filling the frame` —— frame 这个词把模型引到
       「画一张装在画框里的画」，于是出图上、左、右各一道黑色粗边框（下边被
       164:108 的取景裁掉了，所以只有三边）。改成显式**禁止边框/画框/暗角**，
       并把「撑满画面」换一种说法（runs edge to edge），不再用 frame 这个词。
       ⚠ 否定词照旧全留：少一个模型就补灰、补黑、补框。 */
    /* ★★2026-11-12（用户令，第七次）：**回到用户当年认可的那版极简措辞**。
       中间试过 `etching`（出色块）、`line drawing/thin contour`（出照片）、
       `engraving + pure black`（还是照片）、`woodcut`（还是照片+黑框）—— 本地用同一接口
       逐版实测，这个模型根本不改画风。既然风格词全部无效，就不再堆词，
       改回历史那版能出「清爽手绘感」的组合：极简 + 铅笔速写 + 干净线条 + 大量留白。
       关键其实是 `generous white space`：留白多 ⇒ 画面要素少 ⇒ 1bit 上不糊，
       看着才像手绘；图一满，抖完就是照片。
       ⚠ 长度上限 161 字节（prompt[384] 减 scene[224]），改词前先数。 */
    snprintf(b->prompt, sizeof(b->prompt),
             "minimalist pencil sketch, clean simple lines, white paper, generous white space, "
             "no shading, no hatching, no photo, no border, no frame, %s",
             b->scene);
}

bool api_live_fill(int ed, int day, time_t now)
{
    /* ★R157：ed < 0 = 日常/近郊混入（用户口径「日常也会有 AI 生成的新明信片」）。
       此时目的地 = 配网居住城市，一日游（day=1,total=1），照片从基础池随机取。
       ed >= 0 仍是原远行按天寄信，EXP_TBL 对 0..9 全部有效。 */
    const bool daily = (ed < 0);
    if (!daily && ed >= EXP_N) return false;
    const char *dst = daily
        ? ((g_app.cfg && g_app.cfg->city[0]) ? g_app.cfg->city : "附近")
        : EXP_TBL[ed].name;
    const int   total_days = daily ? 1 : EXP_TBL[ed].days;
    char text[192];
    if (!ws_api_diary(dst, day, total_days, g_app.st.weather,
                      text, sizeof(text))) {
        ESP_LOGW(TAG, "★G API 日记生成失败 → 兜底预制片");
        return false;
    }
    /* 照片 = 该目的地组里随机一张预制照（post.bin 素材复用，不出新图） */
    exp_post_index_build();
    exp_souv_load();
    const int pn = daily ? 0 : s_exp_post_n[ed];
    const int photo = daily
        ? g_posts[esp_random() % (unsigned)N_POST_BASE].photo
        : ((pn > 0) ? g_posts[s_exp_post_idx[ed][esp_random() % (unsigned)pn]].photo : 0);
    /* place =「目的地 + 天气」· date = 今天 MM-DD · city = 目的地名（寄信人识别=猫猫）
       ★ 四语：目的地名走 t_()（与成就页/立牌同口径）· 天气词走 T(WEATHER_NAME[..])
         （i18n 表 G 批补的 7 个键）—— EN/JA 态屏上不再是中文。
       ⚠ %02d 会被 -Werror=format-truncation 拦（int 可到 11 位）→ 先夹到 2 位 */
    {
        struct tm tm_now;
        localtime_r(&now, &tm_now);
        snprintf(g_api_p, sizeof(g_api_p), "%s %s", t_(dst),
                 T(WEATHER_NAME[g_app.st.weather]));
        snprintf(g_api_d, sizeof(g_api_d), "%02d-%02d",
                 (tm_now.tm_mon + 1) % 100, tm_now.tm_mday % 100);
    }
    strlcpy(g_api_c, t_(dst), sizeof(g_api_c));
    const char *sp = strchr(text, ' ');
    /* ★R212 修（全量审计）：原来判 `sp - text <= 24`，而 g_api_t 只有 24 字节 ——
       首空格正好在第 24 字节时 cap=25，api_u8ncpy 会写 dst[24]（越界 1 字节）。
       改成按缓冲实际大小判（< sizeof，给 NUL 留位）。 */
    if (sp && sp > text && sp - text < (int)sizeof(g_api_t) && sp[1]) {   /* 标题 ≤8 汉字 */
        api_u8ncpy(g_api_t, text, (int)(sp - text) + 1);
        api_u8ncpy(g_api_n, sp + 1, API_NOTE_MAX);
    } else {
        strlcpy(g_api_t, T("远方来信"), sizeof(g_api_t));
        api_u8ncpy(g_api_n, text, API_NOTE_MAX);
    }
    /* ★ 2026-10-16：模型输出按字库清洗（丢标点/生僻字/emoji），否则上屏是方框 */
    post_font_fix(g_api_t, (int)sizeof(g_api_t));
    post_font_fix(g_api_n, (int)sizeof(g_api_n));
    api_cjk_tighten(g_api_t);                  /* ★R161：模型逐字空格 → 上屏每字中间一格 */
    api_cjk_tighten(g_api_n);
    post_font_fix(g_api_p, (int)sizeof(g_api_p));
    if (!g_api_n[0]) return false;
    g_api_live = (post_t){ g_api_t, g_api_p, g_api_d, g_api_c, g_api_n, photo };
    post_set_got(API_POST_IDX);
    post_mark_unread(API_POST_IDX);       /* ★R157：日常 AI 片也要亮未读 */
    post_arr_set(API_POST_IDX, exp_day_of(now));   /* ★2026-10-26 A12：专用槽也要到达日（详情页日期不能空） */
    ESP_LOGW(TAG, "★★G API 明信片寄到：%s「%s」/%s（photo=%d）",
             daily ? "日常" : "远行", g_api_t, g_api_p, photo);
    return true;                         /* 熔断计数在 ws_api_diary 内部清零 */
}

/* ★R131：把 AI 片的标题交给行程流水（寄出时快照，事后 g_api_live 会被下一张覆盖） */
const char *api_live_title(void) { return g_api_t; }

/* ★A7/A8 共用（定义在 achv_claim 之后；前向声明供 exp_day_mail / 近郊寄信用）：
   mail_pp_total  = 收藏品聚合 mail_pp（铅笔头8/旧邮票15/纸星星夜20）+ 飞鸟帖成就 +15
   mail_force_hit = 聚合必寄位（晴天娃娃+晴 / 写生本+山野 / 玻璃瓶+海滨）+ 夜行者成就+夜雨
   ⚠ 成就行下标（见 ACHV_TBL 上方铁则）：中间插行必须同步改这些常量。
   ★★R124 修（2026-11-03 全面复查）：删「开饭铃」后整表前移 1，但常量没跟着改 ——
     原 4/8/11/12 实际指向漂流瓶/远方来信/旅行家/家的味道：
       · 夜行者（下标 3）的「夜雨必寄」从未生效；
       · 飞鸟帖（7）的 +15% 寄信率从未生效；
       · 冒险装备（10）的背包 +1 从未生效；
       · 「家的味道」（12）被当成背包套白送一格，而真正的旅行家（11）没被检查。
     ⇒ 按当前 ACHV_TBL 实际下标重新对齐（远征票 0 本来就是对的）。 */
#define ACHV_K_NIGHTWALKER   3    /* 夜行者：鹅卵石 + 纸星星   夜雨必寄 */
#define ACHV_K_FEATHER_POST  7    /* 飞鸟帖：纪念邮票册 + 同心结  寄信率 +15% */
#define ACHV_K_GEAR         10    /* 冒险装备：藏宝图 + 旧钥匙 背包 +1 件 */
