/* 行首小圆点（未读标记） */
static void fb_disc(int cx, int cy, int r)
{
    for (int y = cy - r; y <= cy + r; ++y)
        for (int x = cx - r; x <= cx + r; ++x)
            if ((x - cx) * (x - cx) + (y - cy) * (y - cy) <= r * r + 1) fb_put(y, x);
}

