/* ★2026-10-24 D5：随身物品四堆二级页（4 行 = 城市/山野/海滨/通用，行尾件数）。 */
static const char *LOOT_STACK_NAME[4] = { "城市", "山野", "海滨", "通用" };
static void draw_loot_stack_page(void)
{
    fb_clear_white();
#if TOUCH_DEMO
    fb_back_arrow();
#endif
    fb_text_c(ZF_FONT_TITLE, 100, 12, t_(LOOT_CAT_NAME[2]));
    for (int k = 0; k < 4; ++k) {
        const char *nm = t_(LOOT_STACK_NAME[k]);      /* ★先取将上屏那一份（英文更宽）*/
        fb_text_l_fit(ZF_FONT_TITLE, 12, WIFI_ROW_Y[k], nm, 130);
        /* ★R204（用户报「随身二级页没有红点，看不出哪堆是新的」）：未读 ● 贴在堆名末尾，
           落点按**将上屏**的名字量宽 —— 与收藏品分类页 / 列表页同一条口径。 */
        if (loot_stack_unread(k) > 0) {
            int tw = zf_width(ZF_FONT_TITLE, nm);
            if (tw > 130) tw = 130;
            fb_disc(12 + tw + 4 + 2, WIFI_ROW_Y[k] + 6, 2);
        }
        char cn[16];
        snprintf(cn, sizeof(cn), "%d", loot_stack_cnt(k));
        fb_text_r(ZF_FONT_BODY, 184, WIFI_ROW_Y[k] + 1, cn);
        if (g_cat_sel == k) draw_row_sel(WIFI_ROW_Y[k]);
    }
    ESP_LOGI(TAG, "页：随身四堆（光标 %d）", g_cat_sel);
}

/* ══ 2026-10-24 版式 D6：物品介绍行（g_loot_desc，顺序 = g_loot 下标）══
 * ★2026-10-25 正稿 178 条（≤13 全角）。
 * ★R147 核：原注释写「英文/日文翻译待补，非中文态暂回退中文」**已过时** ——
 *   178 条逐条比对，`i18n_table_data.h` / `post_i18n_data.h` 覆盖率 178/178，
 *   上屏也走 `t_(dc)`（见下方 D1 分支），非中文态正常出译文。注释债已清。
 * i >= N_LOOT（两铃等虚拟件）返回 NULL = 详情页不画介绍行（D2 消耗品版式）。
 * ⚠ 表本体在 `loot_system.c:258`，声明在 `loot_data.h`；
 *   原先这里 `#include "loot_desc_data.h"`，那个头在重构后只剩一行说明注释，
 *   是空壳 include（★R147 删）。 */

/* ══ D4：携带角标（右上，热区 x55..150 / y42..70）══
 * 反白 = 黑底白字 + 1px 白色弧形描边 + 外圈黑框（HANDOVER §三 口径）。
 * ⚠ 铁律 16：反相前先把热区整块刷成均匀白底（否则图标墨迹翻成白斑）。
 * ⚠ 铁律 17：白描边与黑框共用 fb_in_rrect 同一圆角判定（rr3，四角不错位）。 */
static bool fb_in_rrect(int x, int y, int l, int t, int r, int b)
{
    if (x < l || x > r || y < t || y > b) return false;
    const int dx = (x - l < r - x) ? (x - l) : (r - x);
    const int dy = (y - t < b - y) ? (y - t) : (b - y);
    if (dx >= 3 || dy >= 3) return true;          /* 角外区域 = 矩形 */
    return (dx + dy) >= 3;                        /* 3px 45° 切角（与 loot_tag_draw 同款） */
}

/* 白字绘制（角标反白用）：与 fb_text_c 同构，墨点写 255；ink 顶对齐 y。 */
static void fb_text_c_inv(int kind, int cx, int y, const char *utf8)
{
    const char *p = utf8;
    uint32_t cp;
    int n, pen = cx - zf_width(kind, utf8) / 2;
    while ((n = utf8_next(p, &cp)) != 0) {
        int h = 0, rb = 0, adv = 0;
        const uint8_t *b = zf_glyph(kind, cp, &h, &rb, &adv);
        if (b) {
            int top = 0;
            bool any = false;
            for (int rr2 = 0; rr2 < h && !any; ++rr2)
                for (int c = 0; c < 8 * rb; ++c)
                    if (ZF_BIT(b, rr2, rb, c)) { top = rr2; any = true; break; }
            for (int rr2 = any ? top : 0; rr2 < h; ++rr2)
                for (int c = 0; c < 8 * rb; ++c)
                    if (ZF_BIT(b, rr2, rb, c)) {
                        const int yy = y + (rr2 - (any ? top : 0)), xx = pen + c;
                        if (yy >= 0 && yy < EPD_H && xx >= 0 && xx < EPD_W) fb[yy][xx] = 255;
                    }
        }
        pen += adv ? adv : ((kind == ZF_FONT_TITLE) ? ZF_TITLE_CJK_ADV : ZF_CJK_ADV);
        p += n;
    }
}

/* ★2026-10-25 修（用户令）：角标恢复**原版小尺寸**（图右上、右缘 x138、y48..63、宽=文字+12，
   与旧 loot_tag_draw 同几何）；删最外层黑框。两态配色：
   · 可携带 = 白外描边 + 黑框 + **白底黑字**；
   · 携带中 = 白外描边 + 黑框 + **黑底白字**。
   热区随角标实际矩形（s_badge_* 供 tap 用）。 */
static int s_badge_l = 96, s_badge_t = 47, s_badge_r = 139, s_badge_b = 64;
static void draw_carry_badge(bool carried)
{
    const char *txt = t_(carried ? "携带中" : "可携带");
    /* ★R207（用户令：所有气泡/角标的文字与左右框边收紧）：+12 → +8（左右各 4px）。 */
    const int w  = zf_width(ZF_FONT_BODY, txt) + 8;
    const int x1 = 138, x0 = x1 - w, y0 = 48, y1 = y0 + 15;
    for (int y = y0 - 1; y <= y1 + 1; ++y)         /* 白外描边层 + 盖图标旧墨 */
        for (int x = x0 - 1; x <= x1 + 1; ++x)
            if (y >= 0 && y < EPD_H && x >= 0 && x < EPD_W) fb[y][x] = 255;
    /* ★2026-10-25 修（用户报「可携带态全黑无字」）：fb_in_rrect 是**含内部**判定，
       旧「黑框」循环把整个圆角矩形涂成了实心黑 → 黑字画在黑底上不可见。
       正确画法 = 外圈像素减内圈(内缩1px)像素 = **1px 框线**；框内两态分别填白/填黑。 */
    for (int y = y0; y <= y1; ++y)
        for (int x = x0; x <= x1; ++x) {
            const bool outer = fb_in_rrect(x, y, x0, y0, x1, y1);
            const bool inner = fb_in_rrect(x, y, x0 + 1, y0 + 1, x1 - 1, y1 - 1);
            if (outer && !inner) fb_put(y, x);                   /* 1px 黑框线 */
            else if (inner && carried) fb[y][x] = 0;             /* 携带中：黑底 */
        }
    const int cx = (x0 + x1) / 2;
    if (carried) fb_text_c_inv(ZF_FONT_BODY, cx, y0 + 3, txt);   /* 白字 */
    else         fb_text_c(ZF_FONT_BODY, cx, y0 + 3, txt);       /* 黑字（白底） */
    s_badge_l = x0 - 1; s_badge_t = y0 - 1; s_badge_r = x1 + 1; s_badge_b = y1 + 1;
}

/* ★2026-10-25 用户令：消耗品数量角标 —— 黑框白底黑字「x03」（×字形不在点阵字库，用 ASCII x）。
   同角标几何（右缘 x138、y48..63），数量 = item_* 计数。 */
static void draw_qty_badge(int n)
{
    char tx[8];
    snprintf(tx, sizeof(tx), "x%02d", n & 0xFF);
    const int w  = zf_width(ZF_FONT_BODY, tx) + 8;   /* ★R207：+12 → +8（左右各 4px） */
    const int x1 = 138, x0 = x1 - w, y0 = 48, y1 = y0 + 15;
    for (int y = y0 - 1; y <= y1 + 1; ++y)
        for (int x = x0 - 1; x <= x1 + 1; ++x)
            if (y >= 0 && y < EPD_H && x >= 0 && x < EPD_W) fb[y][x] = 255;
    for (int y = y0; y <= y1; ++y)
        for (int x = x0; x <= x1; ++x) {
            const bool outer = fb_in_rrect(x, y, x0, y0, x1, y1);
            const bool inner = fb_in_rrect(x, y, x0 + 1, y0 + 1, x1 - 1, y1 - 1);
            if (outer && !inner) fb_put(y, x);       /* ★修：1px 框线（同携带角标错法） */
        }
    fb_text_c(ZF_FONT_BODY, (x0 + x1) / 2, y0 + 3, tx);
}

static void draw_loot_stack_page(void);            /* ★D5 前向声明 */

/* ── 收藏品详情页底部行的两个查表助手（★R115 新增）──
   原先这段逻辑内联在 `else if (carry)` 分支里，导致「carry=0 但属于套装」的件根本走不到
   查表这一步。抽成函数后，两个分支共用同一套查法。 */
#define EXP_ACHV_ITEMS 3               /* ★R116：「XX之行」= 信物 + 环境件 + 通行档 三件
                                          （成就详情页 EXP 分支列的就是这三个，改这里两处同步） */
static int achv_set_of(int i)          /* 该件所属的第一个套装成就下标，-1 = 不属于任何套装 */
{
    if (i < 0 || i >= N_LOOT) return -1;
    for (int q = 0; q < ACHV_N; ++q) {
        if (ACHV_TBL[q].kind != ACHV_KIND_SET) continue;
        for (int j = 0; j < ACHV_TBL[q].n; ++j)
            if (ACHV_TBL[q].it[j] == i) return q;
    }
    return -1;
}

static int exp_dest_of_item(int i)     /* 该件是哪个目的地的信物/环境件，-1 = 不是 */
{
    if (i < 0 || i >= N_LOOT) return -1;
    for (int ed = 0; ed < EXP_N; ++ed)
        if (EXP_TBL[ed].token == i || EXP_TBL[ed].env == i) return ed;
    return -1;
}

static int achv_exp_of(int ed)         /* 该目的地的「XX之行」成就下标，-1 = 没有 */
{
    for (int q = 0; q < ACHV_N; ++q)
        if (ACHV_TBL[q].kind == ACHV_KIND_EXP && ACHV_TBL[q].it[0] == ed) return q;
    return -1;
}

static void draw_loot_item_page(void)   /* ★2026-10-25 基座接线③：触屏/按键两份逐字合并为一份（语义比对一致），放两版共享区 */
{
    fb_load_ui(UI_LOOT_ITEM);
    /* ★2026-10-22 用户令：「雪花结晶点进去，顶上还是一个收藏品列表」——
       底图烤死的标题是旧串「收藏品列表」，详情页也要显示所属分类（纪念品/随身物品/…）。
       ★R208 修（复查）：右栏页码擦白带原来排在标题**之后**，会把英文/日文长分类名
       （如 "Carry Items" / 「消耗品」）的右缘削掉 2px。现在先擦右栏、再擦标题、最后画页码。 */
    fb_fill_white(131, 8, 199, 27);
    if (g_loot_cat >= 0 && g_loot_cat < N_LOOT_CAT) {
        fb_fill_white(36, 4, 164, 27);
        fb_text_c(ZF_FONT_TITLE, 100, 12, t_(LOOT_CAT_NAME[g_loot_cat]));
    }
    /* ★★ R28 实机修复（用户：「标题一长条、字被切」）：底图（槽 30/28）烤的是**旧版式**墨迹
       —— 旧 88×88 图标 @(56,42)、旧名字 y134、旧两行说明 y154/167、旧 got 行 y182。
       新版式（图标 72×72 @(64,48) / 名 135 / 副文案 152）盖不全 ⇒ 新旧两截叠加 = 一长条 + 字被切。
       ⇒ 画自己的内容前先擦两块（避开底图烤的左右三角 y44..104 的 x<41 / x>159 区）：
         · 图标窗 41..159 × 38..119（旧图标残留整块清，新图标随后整块覆盖）
         · 下方整带 y120..199（旧名/旧说明/旧 got 全清，再画名/副文案/按钮）
         ★2026-10-17 版式下移：两窗随图标 40→48 各下移 8px（30..111→38..119 / 112..199→120..199） */
    fb_fill_white(41, 34, 159, 119);
    fb_fill_white(0, 120, 199, 199);
    /* ★ 详情页走**显示序** g_loot_view（R26 起 = 拥有列表内的序，触屏版同源）。 */
    const int cnt = loot_owned_cnt();
    if (cnt <= 0) { draw_loot_list_page(); return; }
    int k = g_loot_view % cnt;
    if (k < 0) k = 0;
    const int i = loot_order(k);
    if (i < 0) { draw_loot_list_page(); return; }
    /* ★ 页码 = 运行时数据（右 x191 · 墨迹顶 y13；必须在 fb_load_ui() 之后画）。
       （右栏擦白已在函数开头做过 —— 那里先擦再画标题，避免削掉长分类名的右缘。） */
    {
        char lp[16];
        snprintf(lp, sizeof(lp), "%d/%d", (int)(k + 1) % 1000, cnt % 1000);
        fb_text_r(ZF_FONT_BODY, 191, 13, lp);
    }
    /* ★★2026-10-19 两铃虚拟件：72px 消耗品图标 @(64,48)（同商店）+ 名字行带「持有N个」，触屏版同源 */
    char nb[32];
    if (i >= N_LOOT) {
        /* ★R77：虚拟消耗品全部走消耗品图标表（改名卡 = 原晴天符图 3、好运铃 = 铃铛图 5） */
        fb_blit_item_icon(loot_v_icon(i));
        snprintf(nb, sizeof(nb), "%s", t_(loot_name_of(i)));   /* ★数量改由右上 ×N 角标表达 */
        fb_text_c_fit(ZF_FONT_TITLE, 100, DETAIL_NAME_Y, nb, 184);
        /* ★2026-10-26 修（消耗品走查）：这里原来先画一次数量角标，但键名只认好运铃/开饭铃/许愿签
           ⇒ 猫薄荷/小鱼饼干/提神草/召回币会短暂显示成"许愿签的数量"。下方统一角标（cn>0 时）
           会覆盖同一块区域，所以直接删掉这次重复绘制，只保留那一处（唯一真源）。 */
    } else {
        /* ★★ 大图标按件运行时绘制（2026-10-18：88 源原样直贴 88×88 @(56,36)，用户令「烧 88」）。 */
        fb_blit_loot_icon_big(i);
        fb_text_c_fit(ZF_FONT_TITLE, 100, DETAIL_NAME_Y, t_(loot_name_of(i)), 184);
    }
    /* ★2026-10-24 D1 四行版式：介绍 148（g_loot_desc，虚拟件无 → 不画）+ 功能 164。 */
    if (i < N_LOOT) {
        const char *dc = loot_desc_of(i);
        const bool usable2 = loot_is_usable(i);
        /* ★D2（使用型：功效 148 不压按钮带 + ×N 角标）/ ★D1（其余：介绍 148 + 功能 164）。 */
        if (usable2) draw_qty_badge(loot_nvs_i32(i == 21 ? "item_dandelion" :
                                                 i == 22 ? "item_sleepherb" : "item_recall", 0));
        if (usable2) {
            fb_text_c_fit(ZF_FONT_BODY, 100, 148, t_(loot_note_of(i)), 184);
        } else {
            if (dc) fb_text_c_fit(ZF_FONT_BODY, 100, 148, t_(dc), 184);
            fb_text_c_fit(ZF_FONT_BODY, 100, 164, t_(loot_note_of(i)), 184);
        }
    } else {
        fb_text_c_fit(ZF_FONT_BODY, 100, DETAIL_NOTE_Y, t_(loot_note_of(i)), 184);   /* 两铃虚拟件：D2 版式（功能 148，无介绍） */
    }
    if (i >= N_LOOT) {
        /* ★2026-10-25 阶段7：全部虚拟消耗品统一「用掉它」（5 件：两铃/许愿签/猫薄荷/小鱼饼干/提神草）；
           开饭铃盆里没食 = 「无法使用」。×N 数量角标右上（用户令）。 */
        /* ★R125（用户令 2026-11-03）：开饭铃还要求猫**在家** —— 在外用铃会白扣（回来才吃甚至过期） */
        bool can = (i != LOOT_V_MEAL) || (g_bowl.state == BOWL_FULL && !g_app.st.outside);
        int cn = 0;
        if (i == LOOT_V_LUCK) cn = loot_nvs_i32("item_luckbell", 0);
        else if (i == LOOT_V_RENAME) cn = loot_nvs_i32("item_rename", 0);
        else if (i == LOOT_V_MEAL) cn = loot_nvs_i32("item_mealbell", 0);
        else if (i == LOOT_V_WISH) cn = loot_nvs_i32("item_wish", 0);
        else if (i == LOOT_V_CATNIP) cn = loot_nvs_i32("item_catnip", 0);
        else if (i == LOOT_V_BISCUIT) cn = loot_nvs_i32("item_biscuit", 0);
        else if (i == LOOT_V_HERB) cn = loot_nvs_i32("item_herb", 0);
        if (cn > 0) draw_qty_badge(cn);
        fb_round_rect(8, DETAIL_BTN_Y0, 191, DETAIL_BTN_Y1);
        fb_btn_text_fit(ZF_FONT_TITLE, 8, 191, DETAIL_BTN_Y0 + 8, can ? T("使用") : T("无法使用"), 176);
    } else if (loot_is_usable(i)) {
        /* ★★使用型（B 真消耗）：按钮「用掉它」—— 点了当场生效 + 藏品消失。
           ★召回币（112）只在猫在外面时可用（在家点了白扔）。 */
        bool can = true;
        if (i == LOOT_I_RECALL) {
            /* ★RAM 快照可能没带出门态 → 回读 NVS 兜底（否则按钮会误显示「无法使用」）*/
            const int32_t ots = g_app.st.out_ts ? (int32_t)g_app.st.out_ts
                                                : loot_nvs_i32("out_ts", 0);
            if (ots == 0 || (time_t)ots <= g_app.st.now_local) can = false;
        }
        fb_round_rect(8, DETAIL_BTN_Y0, 191, DETAIL_BTN_Y1);
        fb_btn_text_fit(ZF_FONT_TITLE, 8, 191, DETAIL_BTN_Y0 + 8, can ? T("使用") : T("无法使用"), 176);
    } else if (i < N_LOOT && g_loot[i].carry) {
        /* ★2026-10-24 D4：携带操作改**右上角反白角标**（tap 热区 x55..150/y42..70；
           按键版 POWER 确认同口径）—— 底部按钮删除，底栏只留一行状态文案。 */
        draw_carry_badge(loot_is_carried(i));
        /* ★2026-10-25 用户令：随身件底栏 = 所属套装成就「成就名-1/m」
           （n 恒 1 = 该物品本身；m = 成就需要件数；一件最多归属两个成就，本行显示第一个）。
           无归属 → 携带操作提示。
           ★★R115：行装钥匙类（护照/通行档/信物/环境件）**全表没有套装归属** ⇒ 以前只能落到
           「点角标带上它」这种没信息量的话。现在补两级：先按目的地找「XX之行-1/3」，
           护照/通行档再各给一句定位。查表走上面抽出来的两个助手，别在这里再抄一遍循环。
           ★★R116（用户报「秘鲁之行应该是 1/3，不是 1/1」）：分母 = **3**，与成就详情页对齐 ——
           EXP 类成就（ACHV_KIND_EXP）的 `n` 恒为 1（它判的是「去过没去过」），
           但成就详情页列的是 `token + env + pass` **三件**、条件行写「拥有这三件物品」
           （见 draw_achv_det_page 的 EXP 分支）⇒ 分母必须是 3，否则同一件东西在
           收藏品详情说 1/1、在成就详情说三件，自己打自己。 */
        {
            char buf[48];                           /* ★本分支自备缓冲（外层 buf 不在作用域） */
            const int set_k = achv_set_of(i);
            const int ed    = exp_dest_of_item(i);
            if (set_k >= 0) {
                snprintf(buf, sizeof(buf), "%s-1/%d", t_(ACHV_TBL[set_k].name), ACHV_TBL[set_k].n);
            } else if (ed >= 0) {
                const int ak = achv_exp_of(ed);     /* 优先用成就名（= 详情页成就列表里那个名字）*/
                snprintf(buf, sizeof(buf), "%s-1/%d",
                         t_(ak >= 0 ? ACHV_TBL[ak].name : EXP_TBL[ed].name), EXP_ACHV_ITEMS);
            } else if (i == LOOT_I_PASSPORT) {
                snprintf(buf, sizeof(buf), "%s", T("远行必备"));
            } else if (i == LOOT_I_TICKET || i == LOOT_I_DINGHY || i == LOOT_I_COMPASS) {
                snprintf(buf, sizeof(buf), "%s", T("远行通行档"));
            } else {
                snprintf(buf, sizeof(buf), "%s", loot_is_carried(i) ? T("点角标取下它") : T("点角标带上它"));
            }
            fb_text_c_fit(ZF_FONT_BODY, 100, 186, buf, 184);
        }
    } else if (loot_cat_of(i) == 3) {           /* ★2026-10-22 用户令：纪念品显示「获得日期 + 地点」*/
        loot_got_draw(i);
    } else {
        fb_text_c_fit(ZF_FONT_BODY, 100, 186, T("无需携带 直接生效"), 184);
    }
    ESP_LOGI(TAG, "页：收藏品详情「%s」（%s · %s%s）",
             loot_name_of(i), loot_note_of(i),
             (i >= N_LOOT) ? "消耗品·虚拟件" : (g_loot[i].carry ? "携带型" : "被动型"),
             (i >= N_LOOT) ? "" : (g_loot[i].carry ? (loot_is_carried(i) ? "·携带中" : "·可携带") : ""));
}

static void draw_bag_page(void)
{
    fb_clear_white();
#if TOUCH_DEMO
    fb_back_arrow();                             /* 左上返回 → 功能页 */
#endif
    fb_text_c(ZF_FONT_TITLE, 100, 12, T("背包"));
    const int cap = bag_cap();                    /* ★2026-10-18：动态 6..9 格 */
    /* ★2026-10-18 用户令：扩展走**翻页**（4 行/页 + 右上角页码），不挤一屏。 */
#if TOUCH_DEMO
    const int off = g_bag_page;                   /* 触屏：整页跳偏移 */
    page_draw_pageno(off, cap, 4, PAGENO_R_X);
#else
    const int off = page_off_fixed(g_bag_sel, 4); /* 按键：窗口随光标 */
    page_draw_pageno(off, cap, 4, PAGENO_R_X);
#endif
    for (int r = 0; r < 4 && (off + r) < cap; ++r) {
        const int k = off + r;
        const int i = bag_slot_item(k);
        if (i >= 0) {
            fb_text_l_fit(ZF_FONT_TITLE, ROW_LABEL_X, WIFI_ROW_Y[r], t_(g_loot[i].name), 130);
            fb_text_r(ZF_FONT_TITLE, 188, WIFI_ROW_Y[r], T("携带中"));
        } else {
            fb_text_l(ZF_FONT_TITLE, ROW_LABEL_X, WIFI_ROW_Y[r], "-");
            fb_text_r(ZF_FONT_TITLE, 188, WIFI_ROW_Y[r], T("去选择"));
        }
    }
#if !TOUCH_DEMO
    if (g_bag_sel >= 0 && g_bag_sel < cap) {
        const int r = g_bag_sel - off;
        if (r >= 0 && r < 4) draw_row_sel(WIFI_ROW_Y[r]);
    }
#endif
    ESP_LOGI(TAG, "页：背包（%d 槽 · 第 %d 页 · 光标 %d · tap/POWER = 进选择页）",
             cap, off / 4 + 1, g_bag_sel);
}

/* ★★ 2026-10-12 新增：可携带物品选择页（背包页 tap 一个槽进来）。
   第一项「无」；选定 → 直接写回目标槽（无二次确认）→ 回背包页。 */
static void draw_bag_pick_page(void)
{
    fb_clear_white();
#if TOUCH_DEMO
    fb_back_arrow();                             /* 左上返回 → 背包页（不改动） */
#endif
    fb_text_c(ZF_FONT_TITLE, 100, 12, T("选择携带的物品"));
    int lst[N_LOOT + 1];
    const int cnt = bag_pick_list(lst);
#if TOUCH_DEMO
    const int off = g_bag_page;
    page_draw_pageno(g_bag_page, cnt, 4, PAGENO_R_X);
#else
    const int off = page_off_fixed(g_bag_sel, 4);
    page_draw_pageno(off, cnt, 4, PAGENO_R_X);
#endif
    for (int r = 0; r < 4 && (off + r) < cnt; ++r) {
        const int i = lst[off + r];
        fb_text_l_fit(ZF_FONT_TITLE, ROW_LABEL_X, WIFI_ROW_Y[r],
                      (i < 0) ? T("无") : t_(g_loot[i].name), 160);
    }
#if !TOUCH_DEMO
    if (g_bag_sel >= 0 && g_bag_sel < cnt) {
        const int r = g_bag_sel - off;
        if (r >= 0 && r < 4) draw_row_sel(WIFI_ROW_Y[r]);
    }
#endif
    ESP_LOGI(TAG, "页：选择携带的物品（目标槽 %d · 候选 %d 项 · 光标 %d）",
             g_bag_pick_slot, cnt, g_bag_sel);
}

/* ★★★ 2026-10-13 新增（用户：「背包点四个槽 → 选择页，点某件先进该件**详情页**；
   详情页和收藏品详情基本相同，但**没有左右切换的按钮、没有可携带的标签**
   （因为从这里进去选的都是可携带的物品）；点下方携带/替换按钮后**立即跳转回列表页**」）。
   页面 = **白底自绘**（不 load UI_LOOT_ITEM 底图 ⇒ 天然没有那两枚烤死的左右三角）；
   图标 72×72 @(64,48) / 名 y135 / 简介 y152 / 底部全宽圆角按钮 —— 与收藏品详情同一批常量（2026-10-17 随版式下移）。
   按钮文案：目标槽**空** → 「携带」；目标槽**已有件** → 「替换」。
   底部按钮点击 → bag_set_slot(目标槽, 该件) 写回 → 回 PG_BAG_PICK（选择列表页）。 */
static void draw_bag_item_page(void)
{
    fb_clear_white();
#if TOUCH_DEMO
    fb_back_arrow();                             /* 左上返回 → 选择列表页 */
#endif
    /* ★2026-10-13：列表页标题改用「收藏品列表」键（与九宫格那个 54px 窄位的
       「收藏品」分开）。英文态两键同译 Keepsakes ⇒ 英文观感零变化；
       日文态这里出「コレクション」全称，九宫格出短名「お宝」。 */
    fb_text_c(ZF_FONT_TITLE, 100, 12, T("收藏品列表"));
    const int i = g_bag_item;
    if (i < 0 || i >= N_LOOT) {                  /* 兜底（理论进不来）：回选择页 */
        ESP_LOGW(TAG, "携带详情页：g_bag_item=%d 非法 → 回选择页", i);
        return;
    }
    fb_blit_loot_icon_big(i);                        /* 大图标 88×88 @(56,36) */
    fb_text_c_fit(ZF_FONT_TITLE, 100, DETAIL_NAME_Y, t_(g_loot[i].name), 184);
    fb_text_c_fit(ZF_FONT_BODY,  100, DETAIL_NOTE_Y, t_(g_loot[i].note), 184);
    /* 底部按钮：目标槽空 → 「携带」；有件 → 「替换」（用户口径「携带/替换按钮」）。
       ★ 不画可携带标签（用户明确：从这里进来的都是可携带物品，标签多余）。 */
    const bool slot_has = (bag_slot_item(g_bag_pick_slot) >= 0);
    fb_round_rect(8, DETAIL_BTN_Y0, 191, DETAIL_BTN_Y1);
    fb_btn_text_fit(ZF_FONT_TITLE, 8, 191, DETAIL_BTN_Y0 + 8,
                    slot_has ? T("替换") : T("携带"), 176);
    ESP_LOGI(TAG, "页：携带详情「%s」（目标槽 %d%s）",
             g_loot[i].name, g_bag_pick_slot,
             slot_has ? "·有件→替换" : "·空→携带");
}

/* ★★★ 2026-10-13 新增：携带详情页底部「携带/替换」按钮动作（触屏 tap / 按键 POWER 共用，两版同口径）：
   把 g_bag_item 写回 g_bag_pick_slot 槽（bag_set_slot 内部处理"腾空 + 落 NVS + 槽表自洽"），
   然后**立即回选择列表页** PG_BAG_PICK（用户口径「点击后立即跳转回列表页」）。
   选择页光标落回「该项」所在行（若该项已携带 → 不在候选里，退化为第 1 行「无」）。 */
static void bag_item_carry_action(void)
{
    if (g_bag_item < 0 || g_bag_item >= N_LOOT) return;
    bag_set_slot(g_bag_pick_slot, g_bag_item);
    /* 回选择页：光标定位到该项（用于按键版有光标；触屏版进页 sel 清 -1，不影响）。
       bag_pick_list 第一项是「无」，故候选行号 = 项在候选里的下标。 */
    g_bag_sel = 0;
    int lst[N_LOOT + 1];
    const int cnt = bag_pick_list(lst);
    for (int r = 0; r < cnt; ++r) if (lst[r] == g_bag_item) { g_bag_sel = r; break; }
    go_page(PG_BAG_PICK);
}

static void draw_bag_swap_page(void)
{
    fb_clear_white();
#if TOUCH_DEMO
    fb_back_arrow();                             /* 左上返回 = 取消不背（回收藏详情） */
#endif
    fb_text_c(ZF_FONT_TITLE, 100, 12, T("替换哪一件"));
    const int cap = bag_cap();                    /* ★2026-10-18：动态 6..9 格 */
    /* ★2026-10-18：与背包页同口径改翻页（4 行/页 + 右上角页码），5..9 格不挤一屏。 */
#if TOUCH_DEMO
    const int off = g_bag_page;
    page_draw_pageno(off, cap, 4, PAGENO_R_X);
#else
    const int off = page_off_fixed(g_bag_sel, 4);
    page_draw_pageno(off, cap, 4, PAGENO_R_X);
#endif
    for (int r = 0; r < 4 && (off + r) < cap; ++r) {
        const int i = bag_slot_item(off + r);
        if (i >= 0) fb_text_l(ZF_FONT_TITLE, ROW_LABEL_X, WIFI_ROW_Y[r], t_(g_loot[i].name));
    }
#if !TOUCH_DEMO
    if (g_bag_sel >= 0 && g_bag_sel < cap) {
        const int r = g_bag_sel - off;
        if (r >= 0 && r < 4) draw_row_sel(WIFI_ROW_Y[r]);
    }
#endif
    ESP_LOGI(TAG, "页：替换哪一件（第 %d 页 · 选定一件 = 带上「%s」换下它）",
             off / 4 + 1, (g_bag_new >= 0) ? g_loot[g_bag_new].name : "?");
}

/* 两个确认页共用的双空心框（tap/选定那颗由 bag_inv_inside 取反；inv<0 = 无选中） */
static void bag_conf_btns(int inv)
{
    fb_round_rect(BAG_BTN2_L0, BAG_BTN2_Y0, BAG_BTN2_L1, BAG_BTN2_Y1);   /* 左「取消」 */
    fb_text_c(ZF_FONT_TITLE, (BAG_BTN2_L0 + BAG_BTN2_L1) / 2, 124, T("取消"));
    fb_round_rect(BAG_BTN2_R0, BAG_BTN2_Y0, BAG_BTN2_R1, BAG_BTN2_Y1);   /* 右「确定」 */
    fb_text_c(ZF_FONT_TITLE, (BAG_BTN2_R0 + BAG_BTN2_R1) / 2, 124, T("确定"));
    if (inv == 0)      bag_inv_inside(BAG_BTN2_L0, BAG_BTN2_Y0, BAG_BTN2_L1, BAG_BTN2_Y1);
    else if (inv == 1) bag_inv_inside(BAG_BTN2_R0, BAG_BTN2_Y0, BAG_BTN2_R1, BAG_BTN2_Y1);
}

static void draw_bag_swap_conf(void)
{
    fb_clear_white();
    fb_text_c(ZF_FONT_TITLE, 100, 12, T("确认替换"));
    char l1[64], l2[64];
    snprintf(l1, sizeof(l1), T("带上 %.40s"), (g_bag_new    >= 0) ? t_(g_loot[g_bag_new].name)    : "?");
    snprintf(l2, sizeof(l2), T("换下 %.40s"), (g_bag_victim >= 0) ? t_(g_loot[g_bag_victim].name) : "?");
    /* ★R193：与其它确认页统一 —— 两行正文落到 y68 / y94（末行墨迹到 103，离按钮顶 117 = 14px）。 */
    fb_text_c(ZF_FONT_TITLE, 100, 68, l1);
    fb_text_c(ZF_FONT_TITLE, 100, 94, l2);
    bag_conf_btns(g_bag_btn);
    ESP_LOGI(TAG, "页：确认替换（%s / %s · 按钮 %s）", l1, l2, g_bag_btn < 0 ? "无" : (g_bag_btn ? "确定" : "取消"));
}

/* 替换页第 k 行（触屏 tap / 按键 POWER 共用）：换下它并背上新件 → 二次确认 */
static void bag_swap_pick(int k)
{
    const int i = bag_slot_item(k);
    if (i < 0) return;
    g_bag_victim = i;
#if TOUCH_DEMO
    g_bag_btn    = -1;       /* 触屏：进页无选中，tap 单段式直接执行 */
#else
    g_bag_btn    = 0;        /* ★按键版（用户 10-12 统一口径）：进页即有预选中（取消），只在两按钮间循环 */
#endif
    go_page(PG_BAG_SWAP_CONF);
}

/* 两个确认页的执行/取消（触屏 tap 写好 g_bag_btn 后调 power_click 到这里；按键同款） */
static void bag_conf_execute(void)
{
    if (g_page == PG_BAG_SWAP_CONF) {
        if (g_bag_btn == 1 && g_bag_victim >= 0 && g_bag_new >= 0) {
            loot_carry_set(g_bag_victim, false);
            loot_carry_set(g_bag_new, true);
        }
        g_bag_victim = g_bag_new = -1;
        /* ★R30：按来源回页 —— 详情页进的回详情（原拍板），背包列表进的回背包 */
        go_page(g_bag_from ? PG_BAG : PG_LOOT_ITEM);
    }
}

