/* 网络状态当前档（从位图读）：0 正常（两位全清）/ 1 无网络 / 2 无wifi */
static int tnet_cur(void)
{
    if ((g_tpat_on >> PAT_NET_NONE) & 1) return 1;
    if ((g_tpat_on >> PAT_NET_NOHUB) & 1) return 2;
    return 0;
}

