/* 贴 1bpp 图标（1 = 墨 → fb_put）。 */
static void ota_icon_blit(int x0, int y0, int w, const uint8_t bits[][5], int rows)
{
    for (int r = 0; r < rows; ++r)
        for (int c = 0; c < w; ++c)
            if ((bits[r][c >> 3] >> (7 - (c & 7))) & 1) fb_put(y0 + r, x0 + c);
}

