/* ★2026-11-12 用户令：测试串门页要**跟真实串门一样** —— 顶上不出标题、底下也不出调试文字，
   只留主页那块告示牌（卡片本体 + 名字 + 一句话）。名字只有真好友来访时才有，
   测试态没有数据，先给一根横杠占位（用汉字「一」，TITLE 字库必定有，不会画成方框）。 */
void test_draw_visit_sign(const char *name)
{
    /* 占位横杠用汉字「一」：TITLE 字库必定有字形，不会像 "·" 那样画成空心方框。
       它不是界面文案（真实访客名由调用方传入），所以走常量、不进三语表。 */
    static const char *const PLACEHOLDER = "一";
    fb_apply_patch(PAT_AWAY);                       /* 卡片本体：与主页外出立牌同一张图 */
    fb_text_c_fit(ZF_FONT_TITLE, 69, 159, (name && name[0]) ? name : PLACEHOLDER, 120);
    fb_text_c(ZF_FONT_BODY, 69, 177, T("过来串门玩啦"));
}

static void draw_test_comb(void)
{
    int period = period_visual(test_period(g_app.st.period));   /* 破晓 → 傍晚房间/窗 */
    /* ★R194：与主页同款 —— 天气在下、风景在中、房间（带窗洞）在上 */
    fb_load_land_weather(period, g_twx);
    fb_apply_land_base(g_tbg, period);
    if (test_period(g_app.st.period) == PERIOD_NIGHT) fb_apply_moon(g_app.st.moon_phase);
    fb_apply_room_masked(room_style_get() == ROOM_STYLE_TECH ? AID_ROOM_TECH : AID_ROOM_PLAIN,
                         period);
    fb_apply_bowl(g_bowl.food, g_bowl.state);

    bool has_wifi = ((g_tpat_on >> PAT_NET_NONE) | (g_tpat_on >> PAT_NET_NOHUB)) & 1;
    for (int i = 0; i < N_PATCH; ++i) {
        if (i == PAT_POST || i == PAT_GIFT) continue;      /* 礼物/明信片走组合逻辑 */
        if (i >= PAT_BATT_LOW && i <= PAT_CHG_FULL) continue;  /* 电量片由 g_tbatt 管 */
        if (i == PAT_AWAY) continue;                       /* ★flash16 立牌改到猫后面画（盖住猫） */
        if ((g_tpat_on >> i) & 1) fb_apply_patch(i);       /* 无网络/无wifi 按头坐标 */
    }
    /* 礼物/明信片组合（复刻主页 2026-09-26 口径：只开礼物 → 对齐明信片位再 +12px） */
    bool has_post = (g_tpat_on >> PAT_POST) & 1;
    bool has_gift = (g_tpat_on >> PAT_GIFT) & 1;
    if (has_gift) {
        int dx = 0;
        if (!has_post) {
            dx = (int)patch_head_x(PAT_POST) - (int)patch_head_x(PAT_GIFT);
            if (dx < 0) dx = 0;
            dx += 12;
        }
        fb_apply_patch_dx(PAT_GIFT, dx);
    }
    if (has_post) fb_apply_patch(PAT_POST);
    /* 电量片（模拟态）：0 正常不画 / 1 低电量 / 2 充电中 / 3 充满；WiFi 缺位左移补位 */
    static const int BATT_PAT[N_TEST_BATT] = { -1, PAT_BATT_LOW, PAT_CHG, PAT_CHG_FULL };
    int bp = BATT_PAT[g_tbatt];
    if (bp >= 0) {
        if (!has_wifi) fb_apply_patch_dx(bp, (int)patch_head_x(PAT_NET_NONE)
                                             - (int)patch_head_x(bp));
        else           fb_apply_patch(bp);
    }
    fb_apply_cat(g_tpose);
    /* ★气泡测试钩子**只在合成预览生效**（flash21b 用户拍板：测试态绝不影响主页
       正式渲染——主页泡只走 bubble_commit+bubble_peek 正式逻辑）：气泡子页选定食物态（1..4）→
       BUBBLE_PLACE[g_tpose]）——BOOT 切姿态即可逐姿态验「放置表 + 挂侧 + 4 食物」；
       「无」(0) 与不干预(-1) 都不画。 */
    if (g_tbub_test > 0) fb_draw_bubble(g_tbub_test - 1, g_tpose);
    /* ★flash16 用户口径：立牌画在**猫精灵之后** = 立牌挡住猫（贴片 A 层是覆盖面，
       后画者覆盖先画者）。主页 render 现状仍是猫在最上层 —— 用户只点了合成预览，先只改这里。 */
    if ((g_tpat_on >> PAT_AWAY) & 1) fb_apply_patch(PAT_AWAY);
    ESP_LOGI(TAG, "页：合成预览 %s · %s · 姿态 %s(%d) · 贴片位图 0x%03x · 电量=%s（时段 %s%s · 素材视觉=%d）",
             LAND_NAME[g_tbg], WEATHER_NAME[g_twx], POSE_NAME[g_tpose], g_tpose,
             g_tpat_on, TBATT_NM[g_tbatt],
             g_tperiod == TPERIOD_NONE ? "真实" : "模拟",
             g_tperiod == TPERIOD_NONE ? "" : tperiod_name(g_tperiod), period);
}
