        epd_commit(fb_pack(), in_page_sel);
        break;
    case PG_LOOT_CAT:                         /* ★★2026-10-18 收藏品分类页 */
        draw_loot_cat_page();
        epd_commit(fb_pack(), in_page_sel);
        break;
    case PG_LOOT_STACK:                       /* ★2026-10-24 D5：随身四堆二级页 */
        draw_loot_stack_page();
        epd_commit(fb_pack(), in_page_sel);
        break;
    case PG_POST_CAT:                         /* ★★2026-10-18 明信片分类页 */
        draw_post_cat_page();
        epd_commit(fb_pack(), in_page_sel);
        break;
    case PG_TEST_PERIOD:                      /* ★2026-09-29 模拟时段子页 */
        draw_test_period();
        epd_commit(fb_pack(), in_page_sel);
        break;
    case PG_TEST_BG:                          /* 背景图选择（参照窗外风景页） */
        draw_test_bg();
        epd_commit(fb_pack(), in_page_sel);
        break;
    case PG_TEST_COMB:                        /* 合成预览：换姿态/天气增量小 → 局刷判定自己裁 */
        draw_test_comb();
