        break;
    case PG_TEST_TRIP:                                    /* ★2026-11-12：stage0 执行动作，stage1 立即出发 */
        if (g_trip_stage == 0) test_tripmenu_go(g_tripmenu_sel);
        else                   test_trip_start(g_ttrip_sel);
        break;
    case PG_LOOT_CAT:                                     /* ★★分类页：POWER = 进入该类列表 */
        if (g_cat_sel < 0) break;                         /* 触屏进页未选 → 不动作 */
        loot_cat_pick(g_cat_sel);
        break;
    case PG_LOOT_STACK:                                   /* ★D5 二级页：POWER = 打开该堆 */
        if (g_cat_sel < 0) break;
        loot_stack_pick(g_cat_sel);
        break;
    case PG_POST_CAT:
        if (g_cat_sel < 0) break;
        post_cat_pick(g_cat_sel);
        break;
    case PG_TEST_BUB:                                     /* 选定气泡强制态 → 回菜单（不自动跳合成预览） */
        g_tbub_test = (int8_t)g_tbub_sel;                 /* 0=无 · 1..4=BUBBLE_FOOD_NAME[n-1] */
        ESP_LOGI(TAG, "★ 测试：气泡强制态 = %s（-1 自动 / 0 无 / n 气泡食物 · 只影响合成预览 · 深睡或重启回自动）",
                 bub_test_name(g_tbub_test));
        go_page(PG_TEST);
        break;
    case PG_TEST_SPR: g_test_idx = (g_test_idx + N_POSE - 1) % N_POSE;   /* ★上一个姿态 */
                      page_render(true); break;
    case PG_TEST_PAT:                                     /* ★2026-09-26 开关切换；★flash16 电量/网络行进子页 */
        if (g_tpat_sel == PAT_LIST_BATT) {
            g_tbatt_sel = g_tbatt;                        /* 光标从当前模拟态起步 */
            go_page(PG_TEST_BATT);
        } else if (g_tpat_sel == PAT_LIST_NET) {
            g_tnet_sel = tnet_cur();                      /* 光标从当前模拟态起步 */
            go_page(PG_TEST_NET);
        } else {
            g_tpat_on ^= 1u << PAT_LIST[g_tpat_sel];      /* 位图按**片下标**存（与合成预览同口径） */
            page_render(true);
        }
        break;
    case PG_TEST_BATT:                                    /* ★2026-09-26 选定电量模拟态 → 回开关列表 */
        g_tbatt = g_tbatt_sel;
        ESP_LOGI(TAG, "测试：电量模拟态选定 %s", TBATT_NM[g_tbatt]);
        go_page(PG_TEST_PAT);
        break;
    case PG_TEST_NET:                                     /* ★flash16 选定网络态 → 互斥写两位 → 回开关列表 */
        g_tpat_on &= ~((1u << PAT_NET_NONE) | (1u << PAT_NET_NOHUB));   /* 先全清 */
        if (g_tnet_sel == 1) g_tpat_on |= 1u << PAT_NET_NONE;
        if (g_tnet_sel == 2) g_tpat_on |= 1u << PAT_NET_NOHUB;
