                       page_render(true); break;
    case PG_TEST_ANIM:                                     /* ★★2026-10-09 选定 → 播放该段交互动画 */
        if (g_anim_sel < 0 || g_anim_sel >= N_ANIM) break; /* 未选中 → 无动作（触屏进页无选中口径） */
        anim_play(g_anim_sel);
